<?php
namespace Tests\Feature;
use App\Models\{InspeksiMobil,Mobil,PengajuanMobil,TradeIn,Transaksi,User};
use App\Services\{PaymentService,TradeInService};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\{DB,Schema};
use RuntimeException;
use Tests\TestCase;
class TradeInStage9ATest extends TestCase
{
 use DatabaseTransactions;
 private function user(string $role):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$role))->firstOrFail();}
 private function draft(float $offer=50000000):array{$base=PengajuanMobil::findOrFail(1);$n=random_int(10000,99999);$p=new PengajuanMobil();$p->forceFill($base->only(['id_pelanggan','id_kendaraan_pelanggan','merk','model','tipe','tahun','warna','transmisi','bahan_bakar','nomor_polisi','kilometer','harga_harapan','foto','catatan'])+['kode_pengajuan'=>'PJM-TI-'.$n,'nomor_rangka'=>'TI-RANGKA-'.$n,'nomor_mesin'=>'TI-MESIN-'.$n,'status'=>'penawaran_diberikan'])->save();$i=new InspeksiMobil();$i->forceFill(['id_pengajuan'=>$p->id_pengajuan,'id_petugas'=>2,'kilometer'=>1000,'harga_penawaran'=>$offer])->save();return [$p,$i];}
 private function createTrade(float $carPrice=80000000,float $offer=50000000):TradeIn{[$p,$i]=$this->draft($offer);$car=Mobil::where('status','tersedia')->where('harga_jual',$carPrice)->first()??Mobil::where('status','tersedia')->where('harga_jual','>',0)->firstOrFail();return app(TradeInService::class)->create($p->id_pelanggan,$p->id_pengajuan,$i->id_inspeksi,$car->id_mobil,2,'0','QA');}
 public function test_baseline_schema_and_relationships_are_copied():void{$this->assertSame(1,TradeIn::count());$t=TradeIn::firstOrFail();$this->assertSame('trade_in',$t->transaksi->jenis_transaksi);$this->assertTrue($t->pengajuan()->exists());$this->assertTrue($t->inspeksi()->exists());$this->assertTrue($t->mobilDibeli()->exists());$this->assertTrue($t->mobilLamaMasuk()->exists());$this->assertFalse(Schema::hasTable('midtrans_orders'));}
 public function test_create_uses_one_gross_difference_transaction_and_books_car():void{$t=$this->createTrade();$this->assertSame('proses',$t->status);$this->assertSame('trade_in',$t->transaksi->jenis_transaksi);$this->assertEquals((float)$t->harga_mobil_dibeli-50000000,(float)$t->selisih_bayar);$this->assertEquals((float)$t->selisih_bayar,(float)$t->transaksi->total);$this->assertSame('dibooking',$t->mobilDibeli->fresh()->status);$this->assertSame(0,DB::table('penjualan_mobil')->where('id_transaksi',$t->id_transaksi)->count());}
 public function test_server_formula_ignores_client_difference_and_discount_rules():void{$t=$this->createTrade(80000000,50000000);$this->assertEquals((float)$t->harga_mobil_dibeli-50000000,(float)$t->selisih_bayar);$this->expectException(RuntimeException::class);app(TradeInService::class)->create($t->id_pelanggan,$t->id_pengajuan,$t->id_inspeksi,$t->id_mobil_dibeli,2,'90000000',null);}
 public function test_invalid_offer_and_duplicate_trade_are_blocked():void{$base=PengajuanMobil::findOrFail(1);$i=InspeksiMobil::findOrFail(1);$this->expectException(RuntimeException::class);app(TradeInService::class)->create($base->id_pelanggan,$base->id_pengajuan,$i->id_inspeksi,7,2,'0',null);}
 public function test_incoming_payment_is_isolated_and_does_not_create_purchase_or_sale():void{$t=$this->createTrade();$stock=DB::table('sparepart')->sum('stok');app(PaymentService::class)->create($t->id_transaksi,2,'10000000','tunai',null,'QA');$this->assertSame('dp',$t->transaksi->fresh()->status);$this->assertSame(0,DB::table('pembelian_mobil_bekas')->where('id_transaksi',$t->id_transaksi)->count());$this->assertSame(0,DB::table('penjualan_mobil')->where('id_transaksi',$t->id_transaksi)->count());$this->assertSame((string)$stock,(string)DB::table('sparepart')->sum('stok'));}
 public function test_pending_payment_verify_and_overpayment_follow_existing_payment_service():void{$t=$this->createTrade();$svc=app(PaymentService::class);$p=$svc->create($t->id_transaksi,2,(string)$t->selisih_bayar,'transfer',null,null);$this->assertSame('menunggu',$p->status);$svc->verify($p->id_pembayaran,2);$this->assertSame('lunas',$t->transaksi->fresh()->status);$this->expectException(RuntimeException::class);$svc->create($t->id_transaksi,2,'1','tunai',null,null);}
 public function test_finalize_requires_lunas_and_creates_old_inventory_atomically():void{$t=$this->createTrade();$this->expectException(RuntimeException::class);app(TradeInService::class)->finalize($t->id_trade_in);}
 public function test_finalize_completes_both_units_and_customer_vehicle():void{$t=$this->createTrade();app(PaymentService::class)->create($t->id_transaksi,2,(string)$t->selisih_bayar,'tunai',null,null);$before=Mobil::count();$old=app(TradeInService::class)->finalize($t->id_trade_in);$this->assertSame($before+1,Mobil::count());$this->assertSame('trade_in',$old->sumber_mobil);$this->assertSame('tersedia',$old->status);$this->assertSame('terjual',$t->mobilDibeli->fresh()->status);$this->assertSame('selesai',$t->fresh()->status);$this->assertSame('selesai',$t->pengajuan->fresh()->status);}
 public function test_double_finalize_and_duplicate_inventory_are_blocked():void{$t=TradeIn::where('status','selesai')->firstOrFail();$this->expectException(RuntimeException::class);app(TradeInService::class)->finalize($t->id_trade_in);}
 public function test_cancel_only_before_payment_and_unlocks_dealer_car():void{$t=$this->createTrade();$car=$t->mobilDibeli;$app=app(TradeInService::class);$app->cancel($t->id_trade_in);$this->assertSame('dibatalkan',$t->fresh()->status);$this->assertSame('dibatalkan',$t->transaksi->fresh()->status);$this->assertSame('tersedia',$car->fresh()->status);}
 public function test_customer_ownership_and_operations_authorization():void{$t=TradeIn::firstOrFail();$other=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->where('id_user','<>',$t->pelanggan->user->id_user)->first();if($other)$this->actingAs($other)->get('/pelanggan/trade-in/'.$t->id_trade_in)->assertForbidden();$this->actingAs($this->user('pelanggan'))->post('/admin/trade-in/'.$t->id_trade_in.'/cancel')->assertForbidden();}
 public function test_trade_in_does_not_use_trade_in_payment_direction_as_outgoing():void{$t=$this->createTrade();app(PaymentService::class)->create($t->id_transaksi,2,'1','tunai',null,null);$this->assertSame('masuk',DB::table('pembayaran')->where('id_transaksi',$t->id_transaksi)->latest('id_pembayaran')->value('arah'));$this->assertSame(0,DB::table('pembayaran')->where('id_transaksi',$t->id_transaksi)->where('arah','keluar')->count());}
}
